import React, { useState } from "react";
import FormWrapper from "./FormWrapper";

const COLORS = {
  navy: "#050B12",
  charcoal: "#242424",
  card: "#383838",
  orange: "#FF9800",
  orangeHover: "#F57C00",
  white: "#FFFFFF",
  border: "#D1D5DB",
  line: "#E5E7EB",
  text: "#111827",
  muted: "#6B7280",
};

const requirementSections = [
  { id: "mfg", title: "Manufacturing Process / Product Requirement" },
  { id: "sys", title: "System Requirement" },
  { id: "insp", title: "Inspection Requirement" },
  { id: "other", title: "Any Other Requirement" },
];

const createInitialRequirements = () =>
  requirementSections.map((section) => ({
    ...section,
    entries: ["", "", "", ""],
    feasibility: "",
  }));

const FeasibilityToggle = ({ value, onChange, label }) => {
  const nextValue =
    value === "" ? "FEASIBLE" : value === "FEASIBLE" ? "NOT FEASIBLE" : "";

  const active = value !== "";
  const isFeasible = value === "FEASIBLE";

  return (
    <div className="flex flex-col items-center justify-center gap-2">
      <button
        type="button"
        role="switch"
        aria-checked={active}
        aria-label={`${label}: ${value || "not selected"}. Click to change.`}
        onClick={() => onChange(nextValue)}
        className={`relative h-10 w-[76px] rounded-full border transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-[#FF9800] focus:ring-offset-2 ${
          !active
            ? "border-[#6B7280] bg-[#242424]"
            : isFeasible
            ? "border-[#FF9800] bg-[#FF9800]"
            : "border-[#050B12] bg-[#050B12]"
        }`}
      >
        <span
          className={`absolute top-[3px] h-8 w-8 rounded-full bg-white shadow-md transition-all duration-200 ${
            !active
              ? "left-[4px]"
              : isFeasible
              ? "left-[40px]"
              : "left-[4px]"
          }`}
        />
      </button>
      <span
        className={`text-center text-[10px] font-bold leading-tight ${
          !active
            ? "text-[#6B7280]"
            : isFeasible
            ? "text-[#F57C00]"
            : "text-[#050B12]"
        }`}
      >
        {value || "NOT SELECTED"}
      </span>
      <button
        type="button"
        onClick={() => onChange(value === "FEASIBLE" ? "NOT FEASIBLE" : "FEASIBLE")}
        className="text-[10px] font-semibold text-[#6B7280] underline decoration-dotted underline-offset-2 hover:text-[#F57C00]"
      >
        {value === "" ? "Choose status" : "Switch status"}
      </button>
    </div>
  );
};

const FeasibilityReport = () => {
  const [formData, setFormData] = useState({
    slNo: "",
    date: "",
    fromDept: "",
    toDept: "",
    partName: "",
    partNo: "",
    customer: "",
    categoryOfChange: "",
    requirements: createInitialRequirements(),
    resources: "",
    conclusion: "",
    conclusionNotes: "",
    cftMembers: Array.from({ length: 6 }, (_, index) => ({
      id: index + 1,
      name: "",
      date: "",
    })),
    comments: "",
    forwardedTo: "",
  });

  const [savedMsg, setSavedMsg] = useState("");

  const updateField = (field, value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const updateRequirementEntry = (sectionIndex, entryIndex, value) => {
    setFormData((prev) => ({
      ...prev,
      requirements: prev.requirements.map((section, index) =>
        index === sectionIndex
          ? {
              ...section,
              entries: section.entries.map((entry, lineIndex) =>
                lineIndex === entryIndex ? value : entry
              ),
            }
          : section
      ),
    }));
  };

  const updateRequirementStatus = (sectionIndex, value) => {
    setFormData((prev) => ({
      ...prev,
      requirements: prev.requirements.map((section, index) =>
        index === sectionIndex ? { ...section, feasibility: value } : section
      ),
    }));
  };

  const updateMember = (index, field, value) => {
    setFormData((prev) => ({
      ...prev,
      cftMembers: prev.cftMembers.map((member, memberIndex) =>
        memberIndex === index ? { ...member, [field]: value } : member
      ),
    }));
  };

  const handleSave = () => {
    localStorage.setItem("saved_feasibility_report", JSON.stringify(formData));
    setSavedMsg("Feasibility report saved successfully!");
    window.setTimeout(() => setSavedMsg(""), 3000);
  };

  return (
    <FormWrapper
      title="FEASIBILITY REPORT FOR CHANGE REQUEST"
      qfNo="QF / 07 / MRO - 02"
      revDate="10 / 06 / 2015"
      onSave={handleSave}
      onPrint={() => window.print()}
    >
      {savedMsg && (
        <div className="mb-3 rounded border border-green-500 bg-green-50 p-2 text-sm font-bold text-green-800 print:hidden">
          {savedMsg}
        </div>
      )}

      <div className="w-full overflow-hidden border-2 border-[#050B12] bg-white text-[#111827]">
        {/* Original form header */}
        <div className="grid grid-cols-12 border-b-2 border-[#050B12]">
          <div className="col-span-12 border-b-2 border-[#050B12] px-3 py-3 sm:col-span-7 sm:border-b-0 sm:border-r-2">
            <div className="flex min-h-[48px] items-center gap-3">
              <div className="text-sm font-bold uppercase leading-tight">
                SAKTHI
                <br />
                AUTO COMPONENT
                <br />
                LIMITED
              </div>
            </div>
          </div>
          <div className="col-span-12 grid grid-cols-1 divide-y divide-[#D1D5DB] sm:col-span-5">
            <label className="flex items-center gap-2 px-3 py-2 text-xs font-semibold">
              <span className="min-w-[145px]">SL. No (of Change Request) :</span>
              <input
                value={formData.slNo}
                onChange={(e) => updateField("slNo", e.target.value)}
                className="min-w-0 flex-1 border-b border-[#D1D5DB] px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
              />
            </label>
            <label className="flex items-center gap-2 px-3 py-2 text-xs font-semibold">
              <span className="min-w-[145px]">Date :</span>
              <input
                type="date"
                value={formData.date}
                onChange={(e) => updateField("date", e.target.value)}
                className="min-w-0 flex-1 border-b border-[#D1D5DB] px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
              />
            </label>
          </div>
        </div>

        <div className="border-b-2 border-[#050B12] bg-[#F8F9FA] px-2 py-3 text-center">
          <h2 className="text-base font-bold uppercase tracking-wide sm:text-xl">
            FEASIBILITY REPORT FOR CHANGE REQUEST
          </h2>
        </div>

        {/* From and To */}
        <div className="grid grid-cols-12 border-b border-[#050B12]">
          <div className="col-span-12 flex items-center border-b border-[#D1D5DB] px-3 py-2 sm:col-span-8 sm:border-b-0 sm:border-r sm:border-r-[#050B12]">
            <label className="mr-3 text-xs font-bold">FROM :</label>
            <input
              value={formData.fromDept}
              onChange={(e) => updateField("fromDept", e.target.value)}
              className="min-w-0 flex-1 border-b border-transparent bg-transparent px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
            />
          </div>
          <div className="col-span-12 flex items-center px-3 py-2 sm:col-span-4">
            <label className="mr-3 text-xs font-bold">TO :</label>
            <input
              value={formData.toDept}
              onChange={(e) => updateField("toDept", e.target.value)}
              className="min-w-0 flex-1 border-b border-transparent bg-transparent px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
            />
          </div>
        </div>

        {[
          ["Part Name :", "partName"],
          ["Part No :", "partNo"],
          ["Customer :", "customer"],
        ].map(([label, field]) => (
          <div
            key={field}
            className="flex min-h-[29px] items-center border-b border-[#D1D5DB] px-3 py-1"
          >
            <label className="mr-2 min-w-[82px] text-xs font-semibold">{label}</label>
            <input
              value={formData[field]}
              onChange={(e) => updateField(field, e.target.value)}
              className="min-w-0 flex-1 bg-transparent px-1 py-1 text-sm outline-none focus:ring-1 focus:ring-[#FF9800]"
            />
          </div>
        ))}

        {/* Category of change */}
        <div className="border-b-2 border-[#050B12] px-3 py-2">
          <label className="block text-xs font-bold uppercase">CATEGORY OF CHANGE</label>
          <span className="block text-xs text-[#6B7280]">(as per the change request)</span>
          <input
            value={formData.categoryOfChange}
            onChange={(e) => updateField("categoryOfChange", e.target.value)}
            className="mt-1 w-full border-b border-[#D1D5DB] bg-transparent px-1 py-1 text-sm outline-none focus:border-[#FF9800]"
          />
        </div>

        {/* Three-column requirements grid */}
        <div className="grid grid-cols-12 border-b-2 border-[#050B12] bg-[#F8F9FA] text-center text-[10px] font-bold sm:text-xs">
          <div className="col-span-3 border-r-2 border-[#050B12] px-1 py-3 sm:col-span-3">
            REQUIREMENT CATEGORY
          </div>
          <div className="col-span-6 border-r-2 border-[#050B12] px-1 py-3 sm:col-span-6">
            REQUIREMENTS OF THE CHANGE
          </div>
          <div className="col-span-3 px-1 py-3 sm:col-span-3">
            FEASIBLE /<br /> NOT FEASIBLE
          </div>
        </div>

        {formData.requirements.map((section, sectionIndex) => (
          <div
            key={section.id}
            className="grid min-h-[150px] grid-cols-12 border-b-2 border-[#050B12]"
          >
            <div className="col-span-3 flex items-center justify-center border-r-2 border-[#050B12] px-2 py-3 text-center text-[11px] font-medium leading-relaxed sm:text-sm">
              {section.title}
            </div>

            {/* Four individual entry boxes, matching the four ruled lines in the paper form */}
            <div className="col-span-6 border-r-2 border-[#050B12]">
              {section.entries.map((entry, entryIndex) => (
                <div
                  key={entryIndex}
                  className={`flex h-[37px] items-center border-b border-[#D1D5DB] px-2 last:border-b-0 ${
                    entryIndex % 2 === 1 ? "bg-[#F8F9FA]" : "bg-white"
                  }`}
                >
                  <span className="mr-2 w-4 text-[10px] text-[#9CA3AF]">
                    {entryIndex + 1}.
                  </span>
                  <input
                    value={entry}
                    onChange={(e) =>
                      updateRequirementEntry(sectionIndex, entryIndex, e.target.value)
                    }
                    aria-label={`${section.title}, requirement line ${entryIndex + 1}`}
                    className="h-full min-w-0 flex-1 bg-transparent text-xs outline-none focus:border-b-2 focus:border-[#FF9800]"
                  />
                </div>
              ))}
            </div>

            <div className="col-span-3 flex items-center justify-center px-1 py-3 sm:px-2">
              <FeasibilityToggle
                label={section.title}
                value={section.feasibility}
                onChange={(value) => updateRequirementStatus(sectionIndex, value)}
              />
            </div>
          </div>
        ))}

        {/* Additional resource requirement */}
        <div className="min-h-[150px] border-b-2 border-[#050B12] px-3 py-2">
          <label className="block max-w-[360px] text-xs font-medium leading-5">
            Additional Manufacturing or Inspection or other Resource requirement at
            Foundry / Machine Shop
          </label>
          <textarea
            rows={5}
            value={formData.resources}
            onChange={(e) => updateField("resources", e.target.value)}
            className="mt-2 min-h-[90px] w-full resize-y bg-transparent p-1 text-sm outline-none focus:ring-1 focus:ring-[#FF9800]"
          />
        </div>

        {/* Conclusion */}
        <div className="grid min-h-[120px] grid-cols-12 border-b-2 border-[#050B12]">
          <div className="col-span-8 px-3 py-2 sm:col-span-9">
            <span className="text-xs font-bold uppercase">CONCLUSION :</span>
            <textarea
              value={formData.conclusionNotes}
              onChange={(e) => updateField("conclusionNotes", e.target.value)}
              className="mt-2 min-h-[75px] w-full resize-y bg-transparent p-1 text-sm outline-none focus:ring-1 focus:ring-[#FF9800]"
              aria-label="Conclusion notes"
            />
          </div>
          <div className="col-span-4 flex flex-col justify-center gap-3 border-l-2 border-[#050B12] px-2 sm:col-span-3 sm:px-4">
            {["FEASIBLE", "NOT FEASIBLE"].map((option) => (
              <label key={option} className="flex cursor-pointer items-center gap-2 text-xs">
                <input
                  type="radio"
                  name="conclusion"
                  checked={formData.conclusion === option}
                  onChange={() => updateField("conclusion", option)}
                  className="h-4 w-4 accent-[#FF9800]"
                />
                {option}
              </label>
            ))}
          </div>
        </div>

        {/* CFT members signing area */}
        <div className="grid min-h-[105px] grid-cols-12 border-b-2 border-[#050B12]">
          <div className="col-span-3 flex items-start justify-center border-r-2 border-[#050B12] px-2 py-2 text-center text-xs font-semibold sm:col-span-3">
            CFT MEMBERS SIGN /<br /> DATE
          </div>
          <div className="col-span-9 grid grid-cols-2 gap-x-3 px-3 py-1 sm:col-span-9">
            {formData.cftMembers.map((member, index) => (
              <div key={member.id} className="flex min-h-[32px] items-center gap-1">
                <span className="w-4 text-xs">{index + 1}.</span>
                <input
                  value={member.name}
                  onChange={(e) => updateMember(index, "name", e.target.value)}
                  aria-label={`CFT member ${index + 1} signature`}
                  className="min-w-0 flex-1 border-b border-transparent bg-transparent px-1 text-xs outline-none focus:border-[#FF9800]"
                />
                <input
                  type="date"
                  value={member.date}
                  onChange={(e) => updateMember(index, "date", e.target.value)}
                  aria-label={`CFT member ${index + 1} date`}
                  className="w-[82px] border-b border-transparent bg-transparent text-[9px] outline-none focus:border-[#FF9800] sm:w-[100px]"
                />
              </div>
            ))}
          </div>
        </div>

        {/* Comments and forwarded to */}
        <div className="grid min-h-[115px] grid-cols-12">
          <div className="col-span-7 border-r-2 border-[#050B12] sm:col-span-7">
            <label className="block px-3 py-1.5 text-xs font-bold">COMMENTS :</label>
            <textarea
              value={formData.comments}
              onChange={(e) => updateField("comments", e.target.value)}
              className="min-h-[80px] w-full resize-y bg-transparent px-3 py-1 text-sm outline-none focus:ring-1 focus:ring-inset focus:ring-[#FF9800]"
              aria-label="Comments"
            />
          </div>
          <div className="col-span-5">
            <label className="block px-3 py-1.5 text-xs font-bold">FORWARDED TO :</label>
            <textarea
              value={formData.forwardedTo}
              onChange={(e) => updateField("forwardedTo", e.target.value)}
              className="min-h-[80px] w-full resize-y bg-transparent px-3 py-1 text-sm outline-none focus:ring-1 focus:ring-inset focus:ring-[#FF9800]"
              aria-label="Forwarded to"
            />
          </div>
        </div>
      </div>
    </FormWrapper>
  );
};

export default FeasibilityReport;
